#pragma once
#include "kstationControllerForegroundRuntime.h"
#include "kstationControllerVoiceGlobalPrefixRuntime.h"
namespace kstation {
// Bounded, CPU-independent composition of voice owners. The board supplies
// one already-bound DSP transfer and IRQ owner. route* performs zero-time
// domain handoffs; nextClocks/advanceBefore perform timed work.
class ControllerVoiceServices final {
public:
 enum class Route:uint8_t{Ready,External,Invalid};
 bool bindAll(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_)return false;if(!trigger_.bindVerifiedFirmware(d,image,size)||!feedback_.bindVerifiedFirmware(d,image,size)||!expressionValues_.bindVerifiedFirmware(d,image,size)||!refresh_.bindVerifiedFirmware(d,image,size)||!depth_.bindVerifiedFirmware(d,image,size)||!pitch_.bindVerifiedFirmware(d,image,size)||!parameters_.bindVerifiedFirmware(d,image,size)||!effects_.bindVerifiedFirmware(d,image,size)||!global_.bindVerifiedFirmware(d,image,size)||!arithmetic_.bindVerifiedFirmware(d,image,size)||!rate_.bindVerifiedFirmware(d,image,size)||!filter_.bindVerifiedFirmware(d,image,size)||!shape_.bindVerifiedFirmware(d,image,size)||!curve_.bindVerifiedFirmware(d,image,size)||!curveTable_.bindVerifiedFirmware(d,image,size)||!pulse_.bindVerifiedFirmware(d,image,size)||!tablePair_.bindVerifiedFirmware(d,image,size)||!levels_.bindVerifiedFirmware(d,image,size)||!modulation_.bindVerifiedFirmware(d,image,size)||!flags_.bindVerifiedFirmware(d,image,size)||!pan_.bindVerifiedFirmware(d,image,size)||!tail_.bindVerifiedFirmware(d,image,size)||!releaseAbove_.bindVerifiedFirmware(d,image,size))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool globalActive()const{return global_.active();}bool foregroundGlobalActive()const{return global_.active()&&globalParent_==Parent::Foreground;}bool refreshActive()const{return refresh_.active();}ControllerVoiceRefreshRuntime::Request parameterRefreshRequest()const{return refresh_.request();}bool completeParameterRefreshChild(VoiceRefreshTask::Child child,uint32_t value=0){return !global_.active()&&refresh_.completeChild(child,value);}
 Route routeForeground(ControllerForegroundRuntime&fg,ControllerDeviceState&d,ControllerDspTransferRuntime&dsp){if(bound_!=&d||!dsp.boundTo(d))return Route::Invalid;if(global_.active())return routeGlobal(d,dsp);auto q=fg.request();return routeForeground(fg,d,dsp,&q);}
 // Null means no pending request; an active global owner ignores the snapshot.
 // Never retain this snapshot across route/advance, an IRQ or a board tick.
 Route routeForeground(ControllerForegroundRuntime&fg,ControllerDeviceState&d,ControllerDspTransferRuntime&dsp,const ControllerForegroundRuntime::Request*request){if(bound_!=&d||!dsp.boundTo(d))return Route::Invalid;if(global_.active())return routeGlobal(d,dsp);if(!request)return Route::Ready;const auto&q=*request;using K=ControllerForegroundRuntime::RequestKind;using E=ControllerForegroundRuntime::ExpressionService;using N=ControllerForegroundRuntime::NoteService;if(q.kind==K::VoiceGlobal){if(!global_.start())return Route::Invalid;globalParent_=Parent::Foreground;return Route::Ready;}if(q.kind==K::MainChild&&(q.child==MainLoopTask::Child::VoiceFeedback||q.child==MainLoopTask::Child::DspFeedback))return fg.beginMainVoiceFeedback(feedback_,dsp,d)?Route::Ready:Route::Invalid;if(q.kind==K::ExpressionChild){if(q.expressionService==E::PressureTail)return fg.beginExpressionValues(expressionValues_,dsp,d)?Route::Ready:Route::Invalid;expressionKind_=q.expressionService;return fg.beginExpressionRefresh(refresh_,d)?Route::Ready:Route::Invalid;}if(q.kind==K::RefreshChild){using C=VoiceRefreshTask::Child;if(q.refresh.child==C::DspSelect)return fg.beginExpressionRefreshDsp(dsp,d)?Route::Ready:Route::Invalid;if(q.refresh.child==C::Update)return (expressionKind_==E::Pitch?fg.beginExpressionModulationPitch(pitch_,dsp,d):fg.beginExpressionModulationDepth(depth_,dsp,d))?Route::Ready:Route::Invalid;return Route::External;}if(q.kind==K::NoteChild){if(q.noteService==N::DspTail)return fg.beginNoteDspTail(trigger_,dsp,d)?Route::Ready:Route::Invalid;if(q.noteService==N::Release)return fg.beginVoiceReleaseDsp(dsp,d)?Route::Ready:Route::Invalid;if(q.parameterDsp)return fg.beginVoiceParameterDsp(dsp,d)?Route::Ready:Route::Invalid;if(q.buildDsp)return fg.beginVoiceBuildDsp(dsp,d)?Route::Ready:Route::Invalid;if(q.noteService==N::BuildVoice&&q.buildChild==MidiVoiceBuildTask::Child::Allocate)return fg.beginVoiceActivationDsp(dsp,d)?Route::Ready:Route::Invalid;return Route::External;}return q.kind==K::None?Route::Ready:Route::External;}
 bool startFeedback(ControllerVoiceFeedbackRuntime::Kind kind){return bound_&&!feedback_.active()&&!global_.active()&&!refresh_.active()&&feedback_.start(kind);}
 Route routeFeedback(ControllerDeviceState&d,ControllerDspTransferRuntime&dsp){if(bound_!=&d||!dsp.boundTo(d)||!feedback_.active())return Route::Invalid;if(global_.active())return routeGlobal(d,dsp);if(feedback_.awaitingGlobal()){if(!global_.start())return Route::Invalid;globalParent_=Parent::Feedback;}return Route::Ready;}
 unsigned nextFeedback(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerDspTransferRuntime&dsp)const{return global_.active()?global_.nextClocks(d,irq,dsp):feedback_.nextClocks(d,irq,dsp);}
 ControllerVoiceFeedbackRuntime::Result advanceFeedback(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,unsigned budget){if(!global_.active())return feedback_.advanceBefore(d,irq,dsp,budget);auto r=global_.advanceBefore(d,irq,dsp,budget);if(r.returned&&globalParent_==Parent::Feedback){globalParent_=Parent::None;if(!feedback_.resumeGlobal())return {r.clocks,false,ControllerVoiceFeedbackRuntime::Block::Global};}return {r.clocks,false,r.blocked==ControllerVoiceGlobalPrefixRuntime::Block::NeedsInterrupt?ControllerVoiceFeedbackRuntime::Block::NeedsInterrupt:ControllerVoiceFeedbackRuntime::Block::None};}
 bool startParameterRefresh(){return bound_&&!refresh_.active()&&!global_.active()&&refresh_.start(VoiceRefreshTask::Kind::Parameters);}
 Route routeParameterRefresh(ControllerDeviceState&d,ControllerDspTransferRuntime&dsp){if(bound_!=&d||!dsp.boundTo(d)||!refresh_.active())return Route::Invalid;if(global_.active())return routeGlobal(d,dsp);using C=VoiceRefreshTask::Child;auto q=refresh_.request();switch(q.child){case C::None:return Route::Ready;case C::DspSelect:return refresh_.beginDspSelect(dsp,d)?Route::Ready:Route::Invalid;case C::DspAddress:return refresh_.beginDspAddress(dsp,d)?Route::Ready:Route::Invalid;case C::Rebuild:return refresh_.beginParameters(parameters_,dsp,d)?Route::Ready:Route::Invalid;case C::Finalize:return refresh_.beginEffects(effects_,dsp,d)?Route::Ready:Route::Invalid;case C::Extras:if(!global_.start())return Route::Invalid;globalParent_=Parent::Refresh;return Route::Ready;default:return Route::External;}}
 unsigned nextForeground(const ControllerForegroundRuntime&fg,const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerDspTransferRuntime&dsp)const{return global_.active()?global_.nextClocks(d,irq,dsp):fg.nextClocks(d,irq);}
 ControllerForegroundRuntime::Result advanceForeground(ControllerForegroundRuntime&fg,ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,unsigned budget){if(!global_.active())return fg.advanceBefore(d,irq,budget);auto r=global_.advanceBefore(d,irq,dsp,budget);if(r.returned&&globalParent_==Parent::Foreground){globalParent_=Parent::None;if(!fg.completeVoiceGlobal())return {r.clocks,false,ControllerForegroundRuntime::Block::AwaitVoiceGlobal};}return {r.clocks,false,r.blocked==ControllerVoiceGlobalPrefixRuntime::Block::NeedsInterrupt?ControllerForegroundRuntime::Block::NeedsInterrupt:ControllerForegroundRuntime::Block::None};}
 unsigned nextParameterRefresh(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerDspTransferRuntime&dsp)const{return global_.active()?global_.nextClocks(d,irq,dsp):refresh_.nextClocks(d,irq);}
 ControllerVoiceRefreshRuntime::Result advanceParameterRefresh(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,unsigned budget){if(!global_.active())return refresh_.advanceBefore(d,irq,budget);auto r=global_.advanceBefore(d,irq,dsp,budget);if(r.returned&&globalParent_==Parent::Refresh){globalParent_=Parent::None;if(!refresh_.completeChild(VoiceRefreshTask::Child::Extras))return {r.clocks,false,ControllerVoiceRefreshRuntime::Block::AwaitChild};}return {r.clocks,false,r.blocked==ControllerVoiceGlobalPrefixRuntime::Block::NeedsInterrupt?ControllerVoiceRefreshRuntime::Block::NeedsInterrupt:ControllerVoiceRefreshRuntime::Block::None};}
private:
 enum class Parent:uint8_t{None,Foreground,Refresh,Feedback};
 Route routeGlobal(ControllerDeviceState&d,ControllerDspTransferRuntime&dsp){auto q=global_.request();if(q.release)return global_.beginTailRelease(releaseAbove_,d)?Route::Ready:Route::Invalid;if(!q.lane)return Route::Ready;bool ok=false;switch(q.index){case 0:case 1:case 2:case 3:case 4:case 5:case 7:case 8:case 9:ok=global_.beginArithmeticLane(arithmetic_,dsp,d);break;case 6:case 10:case 18:ok=global_.beginRate(rate_,dsp,d);break;case 11:ok=global_.beginFilter(filter_,dsp,d);break;case 12:ok=global_.beginShape(shape_,dsp,d);break;case 13:ok=global_.beginCurve(curve_,dsp,d);break;case 14:ok=global_.beginCurveTable(curveTable_,dsp,d);break;case 15:ok=global_.beginPulse(pulse_,dsp,d);break;case 16:ok=global_.beginTablePair(tablePair_,dsp,d);break;case 17:ok=global_.beginLevels(levels_,dsp,d);break;case 19:ok=global_.beginModulation(modulation_,dsp,d);break;case 20:ok=global_.beginFlags(flags_,dsp,d);break;case 21:ok=global_.beginPan(pan_,dsp,d);break;case 22:ok=global_.beginTail(tail_,dsp,d);break;default:return Route::External;}return ok?Route::Ready:Route::Invalid;}
 ControllerDeviceState*bound_=nullptr;Parent globalParent_=Parent::None;ControllerForegroundRuntime::ExpressionService expressionKind_=ControllerForegroundRuntime::ExpressionService::Pitch;
 ControllerDspTriggerRuntime trigger_{};ControllerVoiceFeedbackRuntime feedback_{};ControllerExpressionValuesRuntime expressionValues_{};ControllerVoiceRefreshRuntime refresh_{};ControllerModulationDepthRuntime depth_{};ControllerModulationPitchRuntime pitch_{};ControllerVoiceParameterRuntime parameters_{};ControllerVoiceEffectsRuntime effects_{};ControllerVoiceGlobalPrefixRuntime global_{};ControllerVoiceGlobalLaneRuntime arithmetic_{};ControllerVoiceGlobalRateRuntime rate_{};ControllerVoiceGlobalFilterRuntime filter_{};ControllerVoiceGlobalShapeRuntime shape_{};ControllerVoiceGlobalCurveRuntime curve_{};ControllerVoiceGlobalCurveTableRuntime curveTable_{};ControllerVoiceGlobalPulseRuntime pulse_{};ControllerVoiceGlobalTablePairRuntime tablePair_{};ControllerVoiceGlobalLevelsRuntime levels_{};ControllerVoiceGlobalModulationRuntime modulation_{};ControllerVoiceGlobalFlagsRuntime flags_{};ControllerVoiceGlobalPanRuntime pan_{};ControllerVoiceGlobalTailRuntime tail_{};ControllerVoiceReleaseAboveRuntime releaseAbove_{};
};
}
